// Modelle für die 120 Möbel aus furni-data2.js (zwölf Serien). Format wie furniture.js: Liste von Teilen {g, c}
// oder [Teile, Leuchtteile]. Ursprung = Mitte der Grundfläche, Vorderseite +z, Wandsachen hängen bei z ≈ -0.46.
import * as THREE from '../vendor/three.module.min.js';

const PI = Math.PI, H = PI / 2, TAU = PI * 2;
function put(g, c, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0) {
  if (rx) g.rotateX(rx);
  if (ry) g.rotateY(ry);
  if (rz) g.rotateZ(rz);
  g.translate(x, y, z);
  return { g, c };
}
const X = (w, h, d, c, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0) => put(new THREE.BoxGeometry(w, h, d), c, x, y, z, rx, ry, rz);
const C = (rt, rb, h, c, x = 0, y = 0, z = 0, seg = 14, rx = 0, ry = 0, rz = 0) => put(new THREE.CylinderGeometry(rt, rb, h, seg), c, x, y, z, rx, ry, rz);
const K = (r, h, c, x = 0, y = 0, z = 0, seg = 12, rx = 0, ry = 0, rz = 0) => put(new THREE.ConeGeometry(r, h, seg), c, x, y, z, rx, ry, rz);
const B = (r, c, x = 0, y = 0, z = 0, sx = 1, sy = 1, sz = 1) => put(new THREE.SphereGeometry(r, 12, 9).scale(sx, sy, sz), c, x, y, z);
const T = (R, t, c, x = 0, y = 0, z = 0, rx = H, ry = 0, arc = TAU) => put(new THREE.TorusGeometry(R, t, 8, 24, arc), c, x, y, z, rx, ry);
function S(w, h, d, c, x = 0, y = 0, z = 0, e = 0.3, ry = 0) { // weicher Klotz
  const g = new THREE.SphereGeometry(1, 12, 8), a = g.attributes.position.array;
  for (let i = 0; i < a.length; i++) a[i] = Math.sign(a[i]) * Math.abs(a[i]) ** e;
  g.userData.soft = e;
  g.scale(w / 2, h / 2, d / 2);
  return put(g, c, x, y, z, 0, ry);
}
function star(r, c, x, y, z, th = 0.03, rx = 0, ry = 0) {
  const sh = new THREE.Shape();
  for (let i = 0; i < 10; i++) { const a = i / 10 * TAU + H, rr = i % 2 ? r * 0.45 : r; i ? sh.lineTo(Math.cos(a) * rr, Math.sin(a) * rr) : sh.moveTo(Math.cos(a) * rr, Math.sin(a) * rr); }
  const g = new THREE.ExtrudeGeometry(sh, { depth: th, bevelEnabled: false });
  g.translate(0, 0, -th / 2);
  return put(g, c, x, y, z, rx, ry);
}
const heart = (s, c, x, y, z, dz = 0.04) => [B(s * 0.27, c, x - s * 0.22, y + s * 0.08, z, 1, 1, dz / s / 0.54), B(s * 0.27, c, x + s * 0.22, y + s * 0.08, z, 1, 1, dz / s / 0.54), X(s * 0.38, s * 0.38, dz, c, x, y - s * 0.12, z, 0, 0, PI / 4)];
const legs = (x, z, h, c, r = 0.035) => [[-x, z], [x, z], [-x, -z], [x, -z]].map(([a, b]) => C(r, r * 0.8, h, c, a, h / 2, b, 8));
const flower = (c, x, y, z) => [C(0.008, 0.008, 0.12, DLEAF, x, y - 0.06, z, 5), B(0.035, c, x, y, z), B(0.015, BUTTER, x, y + 0.03, z)];
const pot = (x, z, r = 0.14, h = 0.2, c = TERRA) => [C(r, r * 0.78, h, c, x, h / 2, z, 14), C(r * 1.05, r * 1.05, 0.04, c, x, h, z, 14), C(r * 0.9, r * 0.9, 0.01, 0x6a4a30, x, h + 0.02, z, 14)];
const disc = (r, c, x, y, z, seg = 24) => C(r, r, 0.012, c, x, y, z, seg); // flach auf dem Boden
const rugEdge = (w, d, c, y = 0.012) => [X(w, 0.012, 0.05, c, 0, y, d / 2 - 0.025), X(w, 0.012, 0.05, c, 0, y, -d / 2 + 0.025), X(0.05, 0.012, d, c, w / 2 - 0.025, y, 0), X(0.05, 0.012, d, c, -w / 2 + 0.025, y, 0)];

